{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_013jejqKjMtYzzKiMkawMpfZ","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"Utils for evaluating policies in LIBERO simulation environments.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n\\\\nimport math\\\\nimport os\\\\n\\\\nimport imageio\\\\nimport numpy as np\\\\nimport tensorflow as tf\\\\nfrom libero.libero import get_libero_path\\\\nfrom libero.libero.envs import OffScreenRenderEnv\\\\n\\\\nfrom experiments.robot.robot_utils import (\\\\n    DATE,\\\\n    DATE_TIME,\\\\n)\\\\n\\\\n\\\\ndef get_libero_env(task, model_family, resolution=256):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Initializes and returns the LIBERO environment, along with the task description.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    task_description = task.language\\\\n    task_bddl_file = os.path.join(get_libero_path(\\\\\\\"bddl_files\\\\\\\"), task.problem_folder, task.bddl_file)\\\\n    env_args = {\\\\\\\"bddl_file_name\\\\\\\": task_bddl_file, \\\\\\\"camera_heights\\\\\\\": resolution, \\\\\\\"camera_widths\\\\\\\": resolution}\\\\n    env = OffScreenRenderEnv(**env_args)\\\\n    env.seed(0)  # IMPORTANT: seed seems to affect object positions even when using fixed initial state\\\\n    return env, task_description\\\\n\\\\n\\\\ndef get_libero_dummy_action(model_family: str):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Get dummy/no-op action, used to roll out the simulation while the robot does nothing.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    return [0, 0, 0, 0, 0, 0, -1]\\\\n\\\\n\\\\ndef get_libero_image(obs):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Extracts third-person image from observations and preprocesses it.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    img = obs[\\\\\\\"agentview_image\\\\\\\"]\\\\n    img = img[::-1, ::-1]  # IMPORTANT: rotate 180 degrees to match train preprocessing\\\\n    return img\\\\n\\\\n\\\\ndef get_libero_wrist_image(obs):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Extracts wrist camera