)\n\n        task_successes = 0\n        print(f\"\\n[Task {task_id+1}/{n_tasks}] {task_description}\", flush=True)\n\n        for ep in range(args.num_episodes):\n            env.reset()\n            init_states = task_suite.get_task_init_states(task_id)\n            obs = env.set_init_state(init_states[ep])\n            done = False\n            t = 0\n            action_queue = deque(maxlen=NUM_OPEN_LOOP_STEPS)\n\n            while t < max_steps + args.num_steps_wait:\n                try:\n                    if t < args.num_steps_wait:\n                        obs, reward, done, info = env.step([0, 0, 0, 0, 0, 0, -1])\n                        t += 1\n                        continue\n\n                    if len(action_queue) == 0:\n                        action_list = get_action_chunk(\n                            vla, processor, obs, task_description, action_head, proprio_proj\n                        )\n                        for a in action_list:\n                            action_queue.append(a)\n\n                    action = action_queue.popleft()\n                    action = normalize_gripper_action(action, binarize=True)\n                    action = invert_gripper_action(action)\n                    obs, reward, done, info = env.step(action.tolist())\n                    if done:\n                        task_successes += 1\n                        total_successes += 1\n                        break\n                    t += 1\n                except Exception as e:\n                    print(f\"  Exception t={t}: {e}\", flush=True)\n                    import traceback; traceback.print_exc()\n                    break\n\n            total_episodes += 1\n            if (ep + 1) % 10 == 0:\n                elapsed = time_mod.time() - t_start\n                eps_per_min = total_episodes / (elapsed / 60) if elapsed > 0 else 0\n                print(f\"  Ep {ep+1}/{args.num_episodes} task_sr={task_successes}/{ep+1} \"\n                      f\"({eps_per_min:.1f} eps/min)\", flush=True)\n\n        task_sr = task_successes / args.num_episodes\n        per_task_results[task_description] = {\n            \"success_rate\": task_sr,\n            \"successes\": task_successes,\n            \"episodes\": args.num_episodes,\n        }\n        print(f\"  => Task SR: {task_sr:.3f} ({task_successes}/{args.num_episodes})\", flush=True)\n        env.close()\n\n    overall_sr = total_successes / total_episodes if total_episodes > 0 else 0\n    elapsed = time_mod.time() - t_start\n    print(f\"\\n{'='*60}\", flush=True)\n    print(f\"Overall SR: {overall_sr:.4f} ({total_successes}/{total_episodes})\", flush=True)\n    print(f\"Time: {elapsed/60:.1f} min\", flush=True)\n\n    results = {\n        \"model\": \"openvla-7b-oft-libero-object\",\n        \"mode\": \"random_prune\",\n        \"suite\": args.suite,\n        \"k_ratio\": args.k_ratio,\n        \"overall_success_rate\": overall_sr,\n        \"total_successes\": total_successes,\n        \"total_episodes\": total_episodes,\n        \"per_task\": per_task_results,\n        \"num_open_loop_steps\": NUM_OPEN_LOOP_STEPS,\n        \"num_images_in_input\": NUM_IMAGES_IN_INPUT,\n        \"use_proprio\": USE_PROPRIO,\n        \"max_steps\": max_steps,\n        \"seed\": args.seed,\n        \"elapsed_minutes\": elapsed / 60,\n        \"timestamp\": time_mod.strftime(\"%Y-%m-%d %H:%M:%S\"),\n    }\n\n    if args.output:\n        out_path = args.output\n    else:\n        out_dir = \"/root/autodl-tmp/importance_margin_vla_compress/eval_results\"\n        os.makedirs(out_dir, exist_ok=True)\n        k_str = str(args.k_ratio).replace(\".\", \"\")\n        out_path = f\"{out_dir}/oft_random_prune_k{k_str}_{args.suite.replace('libero_', '')}.json\"\n\n    with open(out_path, \"w\") as f:\n        json.dump(results, f, indent=2)\n    print(f\"[*] Saved: {out_path}\", flush=True)\n\n    hook_handle.remove()\n\n\nif __name__ == \"__main__\":\n    main()\nSCRIPT_EOF\necho \"Script written