{"type":"assistant","message":{"model":"claude-opus-4-6","id":"msg_019PEYgRuJD7FZrPJLsYP5d4","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_014WKtiDwuehu2VMv7L8ZjSE","name":"mcp__agent-ml-research__ssh_execute","input":{"server":"westd-41074","command":"cat > /root/autodl-tmp/download_oft_mirror.py << 'PYEOF'\nimport os, sys, time, requests\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\n\n# Remove proxy\nfor key in ['http_proxy','https_proxy','HTTP_PROXY','HTTPS_PROXY','all_proxy','ALL_PROXY']:\n    os.environ.pop(key, None)\n\nBASE_URL = \"https://hf-mirror.com/moojink/openvla-7b-oft-finetuned-libero-object/resolve/main\"\nOUT_DIR = \"/root/autodl-tmp/openvla-oft-libero-object\"\n\nFILES = [\n    \"model-00001-of-00004.safetensors\",\n    \"model-00002-of-00004.safetensors\",\n    \"model-00003-of-00004.safetensors\",\n    \"model-00004-of-00004.safetensors\",\n    \"lora_adapter/adapter_model.safetensors\",\n    \"action_head--150000_checkpoint.pt\",\n    \"proprio_projector--150000_checkpoint.pt\",\n]\n\ndef download_file(fname):\n    url = f\"{BASE_URL}/{fname}\"\n    out_path = os.path.join(OUT_DIR, fname)\n    os.makedirs(os.path.dirname(out_path), exist_ok=True)\n    \n    # Check existing file\n    existing_size = 0\n    if os.path.exists(out_path):\n        existing_size = os.path.getsize(out_path)\n    \n    # Get total size\n    try:\n        head = requests.head(url, timeout=30, allow_redirects=True)\n        total = int(head.headers.get('content-length', 0))\n    except:\n        total = 0\n    \n    if existing_size > 0 and existing_size == total:\n        print(f\"[SKIP] {fname}: already complete ({total/1e6:.0f} MB)\", flush=True)\n        return fname, True\n    \n    print(f\"[START] {fname}: downloading {total/1e9:.2f} GB (existing: {existing_size/1e6:.0f} MB)\", flush=True)\n    \n    headers = {}\n    if existing_size > 0:\n        headers['Range'] = f'bytes={existing_size}-'\n    \n    start = time.time()\n    try:\n        r = requests.get(url, headers=headers, stream=True, timeout=600, allow_redirects=True)\n        if r.status_code not in (200, 206):\n            print(f\"[FAIL] {fname}: HTTP {r.status_code}\", flush=True)\n            return fname, False\n        \n        mode = 'ab' if existing_size > 0 and r.status_code == 206 else 'wb'\n        downloaded = 0\n        last_report = start\n        with open(out_path, mode) as f:\n            for chunk in r.iter_content(chunk_size=1024*1024):  # 1MB chunks\n                if chunk:\n                    f.write(chunk)\n                    downloaded += len(chunk)\n                    now = time.time()\n                    if now - last_report > 60:  # Report every 60s\n                        speed = downloaded / (now - start) / 1024 / 1024\n                        pct = (existing_size + downloaded) / total * 100 if total else 0\n                        print(f\"[PROGRESS] {fname}: {pct:.1f}% ({speed:.1f} MB/s)\", flush=True)\n                        last_report = now\n        \n        elapsed = time.time() - start\n        final_size = os.path.getsize(out_path)\n        print(f\"[DONE] {fname}: {final_size/1e9:.2f} GB in {elapsed:.0f}s ({downloaded/elapsed/1024/1024:.1f} MB/s)\", flush=True)\n        return fname, True\n    except Exception as e:\n        elapsed = time.time() - start\n        print(f\"[FAIL] {fname} after {elapsed:.0f}s: {e}\", flush=True)\n        return fname, False\n\nprint(f\"=== OFT Model Download from hf-mirror.com ===\", flush=True)\nprint(f\"Started: {time.strftime('%Y-%m-%d %H:%M:%S')}\", flush=True)\nprint(f\"Output: {OUT_DIR}\", flush=True)\nprint(f\"Files: {len(FILES)}\", flush=True)\nprint(\"\", flush=True)\n\n# Download small files first (sequential), then large files (2 parallel)\nsmall_files = [f for f in FILES if 'model-0000' not in f]\nlarge_files = [f for f in FILES if 'model-0000' in f]\n\nstart_all = time.time()\nresults = {}\n\n# Small files first\nfor f in small_files:\n    name, ok = download_file(f)\n    results[name] = ok\n\n# Large files with 2 parallel workers\nwith ThreadPoolExecutor(max_workers=2) as executor:\n    futures = {executor.submit(download_file, f): f for f in large_files}\n    for future in as_completed(futures):\n        name, ok = future.result()\n        results[name] = ok\n\nelapsed_all = time.time() - start_all\nprint(f\"\\n=== Summary ({elapsed_all:.0f}s total) ===\", flush=True)\nfor f, ok in results.items():\n    status = \"OK\" if ok else \"FAILED\"\n    print(f\"  {f}: {status}\", flush=True)\n\nfailed = [f for f, ok in results.items() if not ok]\nif failed:\n    print(f\"\\nFAILED files: {failed}\", flush=True)\n    sys.exit(1)\nelse:\n    print(f\"\\nAll files downloaded successfully!\", flush=True)\nPYEOF\necho \"Download script written\"","warn":true},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":560,"cache_read_input_tokens":59883,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":560},"output_tokens":8,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"f8a7110f-363a-4d33-839b-6bd2edb40751","uuid":"7cc8f647-46b1-448f-9740-5977287480dc"}
