tempts\"\n    return 1\n}\n\necho \"=== OFT Download FINAL ===\"\necho \"Started: $(date)\"\necho \"PID: $$\"\necho \"\"\n\nFAILED=\"\"\n\nfor f in \\\n    \"lora_adapter/adapter_model.safetensors\" \\\n    \"action_head--150000_checkpoint.pt\" \\\n    \"proprio_projector--150000_checkpoint.pt\" \\\n    \"model-00004-of-00004.safetensors\" \\\n    \"model-00001-of-00004.safetensors\" \\\n    \"model-00002-of-00004.safetensors\" \\\n    \"model-00003-of-00004.safetensors\"; do\n    \n    # Check if already downloaded\n    expected_out=\"$DIR/$f\"\n    if [ -f \"$expected_out\" ]; then\n        sz=$(stat -c%s \"$expected_out\" 2>/dev/null || echo 0)\n        if [ \"$sz\" -gt 1000000 ]; then\n            echo \"[$(date +%H:%M:%S)] SKIP: $f ($sz bytes, already exists)\"\n            continue\n        fi\n    fi\n    \n    download_with_retry \"$f\"\n    if [ $? -ne 0 ]; then\n        FAILED=\"$FAILED $f\"\n    fi\ndone\n\necho \"\"\necho \"=== Completed: $(date) ===\"\nif [ -z \"$FAILED\" ]; then\n    echo \"ALL_SUCCESS\"\n    ls -lh \"$DIR\"\nelse\n    echo \"FAILED:$FAILED\"\nfi\nSHEOF\nchmod +x /root/autodl-tmp/download_oft_final.sh\necho \"Script ready\"","warn":true},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":532,"cache_read_input_tokens":117714,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":532},"output_tokens":1,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"f8a7110f-363a-4d33-839b-6bd2edb40751","uuid":"6f89e635-1aaf-41d4-837f-7cd89c0ef8d2"}
