ard(self, x):\\n        x = self.relu(self.fc1(self.layer_norm1(x)))\\n        for block in self.mlp_resnet_blocks:\\n            x = block(x)\\n        return self.fc2(self.layer_norm2(x))\\n\\n\\nclass L1RegressionActionHead(nn.Module):\\n    def __init__(self, input_dim=4096, hidden_dim=4096, action_dim=7):\\n        super().__init__()\\n        self.action_dim = action_dim\\n        self.model = MLPResNet(\\n            num_blocks=2, input_dim=input_dim * ACTION_DIM, hidden_dim=hidden_dim, output_dim=action_dim\\n        )\\n\\n    def predict_action(self, actions_hidden_states):\\n        batch_size = actions_hidden_states.shape[0]\\n        rearranged = actions_hidden_states.reshape(batch_size, NUM_ACTIONS_CHUNK, -1)\\n        return self.model(rearranged)\\n\\n\\nclass ProprioProjector(nn.Module):\\n    def __init__(self, llm_dim, proprio_dim):\\n        super().__init__()\\n        self.fc1 = nn.Linear(proprio_dim, llm_dim, bias=True)\\n        self.act_fn1 = nn.GELU()\\n        self.fc2 = nn.Linear(llm_dim, llm_dim, bias=True)\\n\\n    def forward(self, proprio):\\n        return self.fc2(self.act_fn1(self.fc1(proprio)))\\n\\n\\n# ---------------------------------------------------------------------------\\n# Pruning hook\\n# ---------------------------------------------------------------------------\\n\\nclass RandomPruningHook:\\n    def __init__(self, k_ratio=0.5):\\n        self.k_ratio = k_ratio\\n        self.logged = False\\n\\n    def __call__(self, module, input, output):\\n        B, N, D = output.shape\\n        keep = max(1, int(N * self.k_ratio))\\n        indices = torch.randperm(N, device=output.device)[:keep].sort().values\\n        pruned = output[:, indices, :]\\n        if not self.logged:\\n            print(f\\\"[Pruning] {N} -> {keep} vision tokens (k={self.k_ratio})\\\", flush=True)\\n            self.logged = True\\n        return pruned\\n\\n\\n# ---------------------------------------------------------------------------\\n# Args / seed / model loading\\n# ---------------------------------------------------------------------------\\n\\ndef parse_args():\\n    p = argparse.ArgumentParser()\\n    p.add_argument(\\\"--k_ratio\\\", type=float, required=True)\\n    p.add_argument(\\\"--suite\\\", default=\\\"libero_object\\\")\\n    p.add_argument(\\\"--num_episodes\\\", type=int, default=50)\\n    p.add_argument(\\\"--seed\\\", type=int, default=7)\\n    p.add_argument(\\\"--output\\\", type=str, default=None)\\n    p.add_argument(\\\"--num_steps_wait\\\", type=int, default=10)\\n    return p.parse_args()\\n\\n\\ndef set_seed(seed):\\n    torch.manual_seed(seed)\\n    torch.cuda.manual_seed_all(seed)\\n    np.random.seed(seed)\\n    import random\\n    random.seed(seed)\\n    torch.backends.cudnn.deterministic = True\\n    torch.backends.cudnn.benchmark = False\\n\\n\\ndef load_model():\\n    from transformers import AutoModelForVision2Seq, AutoProcessor\\n\\n    print(f\\\"[*] Loading OFT model from: {CHECKPOINT_PATH}\\\", flush=True)\\n    vla = AutoModelForVision2Seq.from_pretrained(\\n        CHECKPOINT_PATH,\\n        torch_dtype=torch.bfloat16,\\n        trust_remote_code=True,\\n        low_cpu_mem_usage=True,\\n    ).to(DEVICE)\\n    vla.eval()\\n\\n    if hasattr(vla, \\\"vision_backbone\\\") and hasattr(vla.vision_backbone, \\\"set_num_images_in_input\\\"):\\n        vla.vision_backbone.set_num_images_in_input(NUM_IMAGES_IN_INPUT)\\n        print(f\\\"[*] Set num_images_in_input={NUM_IMAGES_IN_INPUT}\\\", flush=True)\\n\\n    with open(os.path.join(CHECKPOINT_PATH, \\\"dataset_statistics.json\\\")) as f:\\n        vla.norm_stats = json.load(f)\\n\\n    processor = AutoProcessor.from_pretrained(CHECKPOINT_PATH, trust_remote_code=True)\\n\\n    llm_dim = vla.config.text_config.hidden_size\\n    print(f\\\"[*] LLM hidden dim: {llm_dim}\\\", flush=True)\\n\\n    # Action head\\n    action_head = L1RegressionActionHead(input_dim=llm_dim, hidden_dim=llm_dim, action_dim=ACTION_DIM)\\n    action_head = action_head.to(torch.bfloat16).to(DEVICE)\\n    action_head.eval()\\n    ah_path = os.path.join(CHECKPOINT_PATH, \\\"action_head--150000_checkpoint.pt\\\")\\n    ah_state = torch.load(ah_path, map_location=\\\"cpu\\\", weights_only=False)\\n    if \\\"state_dict\\\" in ah_state:\\n        ah_state = ah_state[\\\"state_dict\\\"]\\n    action_head.load_state_dict(ah_state)\\n    print(f\\\"[*] Action head loaded from: {ah_path}\\\", flush=True)\\n\\n    # Proprio projector\\n    proprio_proj = ProprioProjector(llm_dim=llm_dim, proprio_dim=PROPRIO_DIM)\\n    proprio_proj = proprio_proj.to(torch.bfloat16).to(DEVICE)\\n    proprio_proj.eval()\\n    pp_path = os.path.join(CHECKPOINT_PATH, \\\"proprio_projector--150000_checkpoint.pt\\\")\\n    pp_state = torch.load(pp_path, map_location=\\\"cpu\\\", weights_only=False)\\n    if \\\"state_dict\\\" in pp_state:\\n        pp_state = pp_state[\\\"state_dict\\\"]\\n    proprio_proj.load_state_dict(pp_state)\\n    print(f\\\"[*] Proprio projector loaded from: {pp_path}\\\", flush=True)\\n\\n    print(f\\\"[*] GPU mem: {torch.cuda.max_memory_allocated()/1e9:.1f} GB\\\", flush=True)\\n    return vla, processor, action_head, proprio_proj\\n\\n\\n# ---------------------------------------------------------------------------\\n# Observation processing\\n# ---------------------------------------------------------------------------\\n\\ndef center_crop_image(image, crop_scale=0.9):\\n    w, h = image.size\\n    new_w = int(w * math.sqrt(crop_scale))\\n    new_h = int(h * math.sqrt(crop_scale))\\n    left = (w - new_w) // 2\\n    top = (h - new_h) // 2\\n    return image.crop((left, top, left + new_w, top + new_h)).resize((w, h), Image.LANCZOS)\\n\", \"stderr\": \"\", \"return_code\": 0}, \"error\": null, \"metadata\": {\"elapsed_seconds\": 0.44}}"}}}
